31: // NewNamespaceFilter inits the namespace lister and returns a new NamespaceFilter.
32: func NewNamespaceFilter(c *config.NamespaceSelector, client kubernetes.Interface, storer storer.Storer, logger *log.Logger, options ...informers.SharedInformerOption) *NamespaceFilter {
33: 	stopCh := make(chan struct{})
34: 
35: 	factory := informers.NewSharedInformerFactoryWithOptions(client, defaultResyncDuration, options...)
36: 
37: 	lister := factory.Core().V1().Namespaces().Lister()
38: 
39: 	factory.Start(stopCh)
40: 	factory.WaitForCacheSync(stopCh)
41: 
