51: // IsAllowed checks given any namespace, if it's allowed to be scraped by using the NamespaceLister
52: func (nf *NamespaceFilter) IsAllowed(namespace string) bool {
53: 	// By default, we scrape every namespace.
54: 	if nf.c == nil {
55: 		return true
56: 	}
57: 
58: 	// Check if the namespace is already in the cache.
59: 	var allowed bool
60: 	if _, err := nf.storer.Get(namespace, &allowed); err == nil {
61: 		return allowed
62: 	}
63: 
64: 	// Scrape namespaces by honoring the matchLabels values.
65: 	if nf.c.MatchLabels != nil {
66: 		namespaceList, err := nf.lister.List(labels.SelectorFromSet(nf.c.MatchLabels))
67: 		if err != nil {
68: 			nf.logger.Errorf("listing namespaces with MatchLabels: %v", err)
69: 			return true
70: 		}
71: 
72: 		allowed = containsNamespace(namespace, namespaceList)
73: 
74: 		// Save the namespace in the cache.
75: 		_ = nf.storer.Set(namespace, allowed)
