77: 		return allowed
78: 	}
79: 
80: 	// Scrape namespaces by honoring the matchExpressions values.
81: 	// Multiple expressions are evaluated with a logical AND between them.
82: 	if nf.c.MatchExpressions != nil {
83: 		for _, expression := range nf.c.MatchExpressions {
84: 			selector, err := labels.Parse(expression.String())
85: 			if err != nil {
86: 				nf.logger.Errorf("parsing labels: %v", err)
87: 				return true
88: 			}
89: 
